parameters.jsCode:
const raw = $json.candidates[0].content.parts[0].text;

const cleaned = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);

let driveLink_check = "LỖI_KHÔNG_LẤY_ĐƯỢC";
try {
  const shareNodeData = $('Share file').first();
  if (shareNodeData && shareNodeData.json && shareNodeData.json.webViewLink) {
    driveLink_check = shareNodeData.json.webViewLink;
  } else if (shareNodeData && shareNodeData.json && shareNodeData.json.webContentLink) {
    driveLink_check = shareNodeData.json.webContentLink;
  } else {
    driveLink_check = "NODE_SHARE_FILE_KHÔNG_CÓ_LINK";
  }
} catch (error) {
  driveLink_check = "SAI_TÊN_NODE_HOẶC_CHƯA_CHẠY_NODE_TRƯỚC";
}

// 4. Gom hết data lại đẩy đi tiếp cho Postgres
return [{
  json: {
    invoice_id: parsed.invoice_id,
    vendor_name: parsed.vendor_name,
    amount: parsed.amount,
    invoice_date: parsed.invoice_date,
    bank_name: parsed.bank_name,
    bank_code: parsed.bank_code,
    account_name: parsed.account_name,
    account_number: parsed.account_number,
    SenderEmail: $('Edit Fields').first().json.SenderEmail,
    TrackingID: $('Edit Fields').first().json.TrackingID,
    ReceivedDate: $('Edit Fields').first().json.ReceivedDate,
    DriveLink: $('upload').first().json.webViewLink
  }
}];

const items = $input.all();
const newItems = [];

for (const item of items) {
  // Lấy danh sách file từ body của Webhook
  const files = item.json.body.files || [];

  for (const file of files) {
    newItems.push({
      json: {
        sender: item.json.body.sender,
        subject: item.json.body.subject,
        received_date: item.json.body.date
      },
      binary: {
        data: {
          data: file.data, // Chuỗi base64
          mimeType: file.mimeType,
          fileName: file.name
        }
      }
    });
  }
}

return newItems;

